import heapq

def match(orders):
    buy_heap = []  # (-price, seq, id) - max price first, then earliest seq
    sell_heap = []  # (price, seq, id) - min price first, then earliest seq
    orders_info = {}  # id -> dict(side, price, qty, active, seq)
    trades = []
    seq_counter = 0

    for o in orders:
        typ = o[0]
        if typ == 'cancel':
            oid = o[1]
            info = orders_info.get(oid)
            if info and info['active'] and info['qty'] > 0:
                info['active'] = False
            continue

        if typ == 'market':
            _, oid, side, qty = o
            price = None
        else:
            _, oid, side, price, qty = o

        remaining = qty
        seq = seq_counter
        seq_counter += 1
        orders_info[oid] = {'side': side, 'price': price, 'qty': remaining, 'active': True, 'seq': seq}

        if side == 'buy':
            opp_heap = sell_heap
        else:
            opp_heap = buy_heap

        while remaining > 0 and opp_heap:
            top = opp_heap[0]
            if side == 'buy':
                opp_price, opp_seq, opp_id = top
            else:
                neg_price, opp_seq, opp_id = top
                opp_price = -neg_price

            opp_info = orders_info.get(opp_id)
            if not opp_info or not opp_info['active'] or opp_info['qty'] <= 0:
                heapq.heappop(opp_heap)
                continue

            if typ != 'market':
                if side == 'buy' and opp_price > price:
                    break
                if side == 'sell' and opp_price < price:
                    break

            trade_qty = min(remaining, opp_info['qty'])
            if side == 'buy':
                trades.append([oid, opp_id, opp_price, trade_qty])
            else:
                trades.append([opp_id, oid, opp_price, trade_qty])

            remaining -= trade_qty
            opp_info['qty'] -= trade_qty
            orders_info[oid]['qty'] = remaining

            if opp_info['qty'] == 0:
                opp_info['active'] = False
                heapq.heappop(opp_heap)

        orders_info[oid]['qty'] = remaining

        if typ == 'limit' and remaining > 0:
            if side == 'buy':
                heapq.heappush(buy_heap, (-price, seq, oid))
            else:
                heapq.heappush(sell_heap, (price, seq, oid))
        else:
            orders_info[oid]['active'] = False

    return trades

